import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            N = int(next(iterator))
        except StopIteration:
            break

        adj = [[] for _ in range(N + 1)]

        for _ in range(N - 1):
            u = int(next(iterator))
            v = int(next(iterator))
            adj[u].append(v)
            adj[v].append(u)

        if N <= 2:
            results.append("0")
            continue

        degree = [0] * (N + 1)
        for u in range(1, N + 1):
            degree[u] = len(adj[u])

        leaves = 0
        for u in range(1, N + 1):
                if degree[u] == 1:
                    leaves += 1

        if leaves <= 2:
            results.append("0")
        else:
            ans = (leaves - 2) // 2
            results.append(str(ans))

    print('\n'.join(results))

if __name__ == '__main__':
    solve()
